[{'name': 'Docker Buildx Bake', 'description': 'GitHub Action to use Docker Buildx Bake as a high-level build command', 'author': 'docker', 'branding': {'icon': 'anchor', 'color': 'blue'}, 'inputs': {'builder': {'description': 'Builder instance', 'required': False}, 'files': {'description': 'List of bake definition files', 'required': False}, 'workdir': {'description': 'Working directory of bake execution', 'required': False, 'default': '.'}, 'targets': {'description': 'List of bake targets', 'required': False}, 'no-cache': {'description': 'Do not use cache when building the image', 'required': False, 'default': 'false'}, 'pull': {'description': 'Always attempt to pull a newer version of the image', 'required': False, 'default': 'false'}, 'load': {'description': 'Load is a shorthand for --set=*.output=type=docker', 'required': False, 'default': 'false'}, 'provenance': {'description': 'Provenance is a shorthand for --set=*.attest=type=provenance', 'required': False}, 'push': {'description': 'Push is a shorthand for --set=*.output=type=registry', 'required': False, 'default': 'false'}, 'sbom': {'description': 'SBOM is a shorthand for --set=*.attest=type=sbom', 'required': False}, 'set': {'description': 'List of targets values to override (eg. targetpattern.key=value)', 'required': False}, 'source': {'description': 'Remote bake definition to build from', 'required': False}}, 'outputs': {'metadata': {'description': 'Build result metadata'}}, 'runs': {'using': 'node20', 'main': 'dist/index.js'}}, {'name': 'List Bake targets', 'description': 'Generate a list of Bake targets to help distributing builds in your workflow', 'inputs': {'workdir': {'description': 'Working directory', 'default': '.', 'required': False}, 'files': {'description': 'Comma separated list of Bake files', 'required': False}, 'target': {'description': 'Bake target', 'required': False}}, 'outputs': {'targets': {'description': 'List of targets', 'value': '${{ steps.generate.outputs.targets }}'}}, 'runs': {'using': 'composite', 'steps': [{'name': 'Generate', 'id': 'generate', 'uses': 'actions/github-script@v6', 'with': {'script': "let def;
const files = `${{ inputs.files }}` ? `${{ inputs.files }}`.split(',') : [];
const target = `${{ inputs.target }}`;

await core.group(`Validating definition`, async () => {
  let args = ['buildx', 'bake'];
  for (const file of files) {
    args.push('--file', file);
  }
  if (target) {
    args.push(target);
  }
  args.push('--print');

  const res = await exec.getExecOutput('docker', args, {
    ignoreReturnCode: true,
    silent: true,
    cwd: `${{ inputs.workdir }}`
  });
  if (res.stderr.length > 0 && res.exitCode != 0) {
    throw new Error(res.stderr);
  }
  def = JSON.parse(res.stdout.trim());
  core.info(JSON.stringify(def, null, 2));
});

await core.group(`Set output`, async () => {
  const targets = Object.keys(def.target);
  core.info(`targets: ${JSON.stringify(targets)}`);
  core.setOutput('targets', JSON.stringify(targets));
});
"}}]}}]

