[{'name': 'PlatformIO Run', 'description': 'Run PlatformIO project targets over environments declared in platformio.ini', 'author': 'Piotr Rogowski <piotr.rogowski0@gmail.com>', 'branding': {'icon': 'cpu', 'color': 'orange'}, 'inputs': {'environments': {'description': 'Process specified environments (comma separated).', 'required': False}, 'targets': {'description': 'Process specified targets (comma separated).', 'required': False}, 'project-dir': {'description': 'Specify the path to project directory. By default, project-dir is equal to current working directory (CWD).', 'required': False}, 'project-conf': {'description': 'Process project with a custom platformio.ini', 'required': False}, 'jobs': {'description': 'Control a number of parallel build jobs. Default is a number of CPUs in a system.', 'required': False}, 'silent': {'description': 'Suppress progress reporting.', 'required': False}, 'verbose': {'description': 'Shows detailed information when processing environments.', 'required': False}, 'disable-auto-clean': {'description': 'Disable auto-clean of build_dir when platformio.ini or src_dir (project structure) have been modified.', 'required': False}}, 'runs': {'using': 'composite', 'steps': [{'name': 'Cache pip', 'uses': 'actions/cache@v3', 'with': {'path': '~/.cache/pip', 'key': "${{ runner.os }}-pip-${{ hashFiles('**/requirements.txt') }}", 'restore-keys': '${{ runner.os }}-pip-
'}}, {'name': 'Cache PlatformIO', 'uses': 'actions/cache@v3', 'with': {'path': '~/.platformio', 'key': "${{ runner.os }}-${{ hashFiles('**/lockfiles') }}"}}, {'name': 'Set up Python', 'uses': 'actions/setup-python@v5', 'with': {'python-version': '3.10'}}, {'name': 'Install PlatformIO', 'shell': 'bash', 'run': 'python -m pip install --upgrade pip
pip install --upgrade platformio
'}, {'name': 'Run PlatformIO', 'shell': 'bash', 'run': 'environments=${{ inputs.environments }}
targets=${{ inputs.targets }}
project_dir=${{ inputs.project-dir }}
project_conf=${{ inputs.project-conf }}
jobs=${{ inputs.jobs }}
silent=${{ inputs.silent }}
verbose=${{ inputs.verbose }}
disable_auto_clean=${{ inputs.disable-auto-clean }}

args=()

if [ -n "$environments" ]; then args+=("--environment ${environments//,/ -e }"); fi
if [ -n "$targets" ]; then args+=("--target ${targets//,/ -t }"); fi
if [ -n "$project_dir" ]; then args+=("--project-dir $project_dir"); fi
if [ -n "$project_conf" ]; then args+=("--project-conf $project_conf"); fi
if [ -n "$jobs" ]; then args+=("--jobs $jobs"); fi
if [ -n "$silent" ]; then args+=("--silent"); fi
if [ -n "$verbose" ]; then args+=("--verbose"); fi
if [ -n "$disable_auto_clean" ]; then args+=("--disable-auto-clean"); fi

echo $args | xargs pio run
'}]}}]

