[{'name': 'Push Any Git Tag', 'description': 'based on Actions Ecosystem Push Tag - Fixed with additional features.', 'author': 'Actions Ecosystem & theJeff77', 'inputs': {'tag': {'description': 'A Git tag name.', 'type': 'string', 'required': True}, 'message': {'description': 'A message for the Git tag.', 'type': 'string', 'required': False}, 'ref': {'description': 'Commit SHA or ref (tag) to target for the tag.', 'type': 'string', 'required': False}, 'force': {'description': 'Whether or not to force push (overwrite) the tag if it already exists. Useful for walking tags.', 'type': 'boolean', 'required': False, 'default': False}, 'always-pass': {'description': 'If this build step should pass no matter what if ref is missing and the tag push fails.', 'type': 'boolean', 'required': False, 'default': False}}, 'runs': {'using': 'composite', 'steps': [{'name': 'Tag', 'shell': 'bash', 'run': 'tag=${{ inputs.tag }}
message=${{ inputs.message }}
ref=${{ inputs.ref }}
force=${{ inputs.force }}
alwaysPass=${{ inputs.always-pass }}

if [ "$force" = "true" ]; then
  force="-f"
else
  unset force
fi

if [ "$always-pass" = "true" ]; then
  alwaysPass=" || true"
else
  unset alwaysPass
fi

if [ -z "$ref" ]; then
  ref="HEAD"
fi

git config user.name "${GITHUB_ACTOR}"
git config user.email "${GITHUB_ACTOR}@users.noreply.github.com"

git tag -a "${tag}" "${ref}" -m "${message}" ${force} ${alwaysPass}
git push origin "${tag}" ${force} ${alwaysPass}
'}]}, 'branding': {'icon': 'search', 'color': 'yellow'}}]

[{'name': 'Create Issue From pytest log', 'description': 'Create an issue for failed tests from a pytest-reportlog file.', 'inputs': {'log-path': {'description': 'The path to the log file', 'required': True}, 'issue-title': {'description': 'Title of issue being created or updated', 'required': False, 'default': '⚠️ Nightly upstream-dev CI failed ⚠️'}, 'issue-label': {'description': 'Labels to apply to issue', 'required': False, 'default': 'CI'}, 'assignees': {'description': 'Comma-separated users to assign to the issue (no spaces). All assigned users have to have commit rights.', 'required': False, 'default': ''}}, 'outputs': {}, 'branding': {'color': 'red', 'icon': 'alert-triangle'}, 'runs': {'using': 'composite', 'steps': [{'name': 'print environment information', 'shell': 'bash -l {0}', 'run': 'python --version
python -m pip list
'}, {'name': 'install dependencies', 'shell': 'bash -l {0}', 'run': 'python -m pip install pytest more-itertools
'}, {'name': 'produce the issue body', 'shell': 'bash -l {0}', 'run': 'python $GITHUB_ACTION_PATH/parse_logs.py ${{ inputs.log-path }}
'}, {'name': 'create the issue', 'uses': 'actions/github-script@v6', 'with': {'github-token': '${{ github.token }}', 'script': 'const fs = require('fs');
const pytest_logs = fs.readFileSync('pytest-logs.txt', 'utf8');
const title = "${{ inputs.issue-title }}"
const assignees = "${{inputs.assignees}}".split(",")
const workflow_url = `https://github.com/${process.env.GITHUB_REPOSITORY}/actions/runs/${process.env.GITHUB_RUN_ID}`
const issue_body = `[Workflow Run URL](${workflow_url})\n${pytest_logs}`

// Run GraphQL query against GitHub API to find the most recent open issue used for reporting failures
const query = `query($owner:String!, $name:String!, $creator:String!, $label:String!){
  repository(owner: $owner, name: $name) {
    issues(first: 1, states: OPEN, filterBy: {createdBy: $creator, labels: [$label]}, orderBy: {field: CREATED_AT, direction: DESC}) {
      edges {
        node {
          body
          id
          number
        }
      }
    }
  }
}`;

const variables = {
  owner: context.repo.owner,
  name: context.repo.repo,
  label: "${{ inputs.issue-label }}",
  creator: "github-actions[bot]"
}
const result = await github.graphql(query, variables)

// If no issue is open, create a new issue,
// else update the body of the existing issue.
if (result.repository.issues.edges.length === 0) {
  github.rest.issues.create({
    owner: variables.owner,
    repo: variables.name,
    body: issue_body,
    title: title,
    labels: [variables.label],
    assignees: assignees
  })
} else {
  github.rest.issues.update({
    owner: variables.owner,
    repo: variables.name,
    issue_number: result.repository.issues.edges[0].node.number,
    body: issue_body
  })
}
'}}]}}]
